"""Read-only synthesis of three frozen, closed F128 CH/DH source quartets."""
from pathlib import Path
import datetime,hashlib,json,math

A=Path('/root/share/mnt164/huangrulin/host174_storage_recovery/dtc_stage_iia_first16_execution_20261104_v1')
O=A/'root_three_case_synthesis_v1'
PACKS=[('ATAX','B_atax_f128_matched_v1','af69366bb4fe44dd919518150f763a248451a4cdd67a4764c25b2494bec47158'),('MVT','B_mvt_f128_matched_v1','062f7262459e8bac45adeee494038a85b63b73319fe19db7b1dbde3150a440ae'),('BICG','B_bicg_f128_matched_v1','f2b1dfc69e860b56e96ec70f50490458d843a8808f5f7d598852571790401cba')]
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()

def main():
 assert not(O/'MANIFEST.json').exists(),'FROZEN_SYNTHESIS_ALREADY_EXISTS_NO_OVERWRITE'
 O.mkdir(exist_ok=True);rows=[]
 for program,package,pin in PACKS:
  d=A/'agents'/package;assert sha(d/'MANIFEST.json')==pin
  for r in json.loads((d/'MANIFEST.json').read_bytes())['files']:
   p=d/r['path'];assert p.is_relative_to(d)and sha(p)==r['sha256']
  data=json.loads((d/'MATCHED_FOUR_SOURCE_DATA.json').read_bytes())
  by={(r['cell'],r['profile']):r for r in data['four_closed_sources']};assert set(by)=={('CH','P0'),('CH','F128'),('DH','P0'),('DH','F128')}
  c0,cf,d0,df=(by[k]for k in [('CH','P0'),('CH','F128'),('DH','P0'),('DH','F128')])
  sc=c0['cycles']/cf['cycles'];sd=d0['cycles']/df['cycles'];interaction=sd/sc;ratio=cf['cycles']/df['cycles']
  assert math.isclose(interaction,data['matched_performance']['I'],rel_tol=1e-12)
  assert math.isclose(ratio,data['matched_performance']['R_F128'],rel_tol=1e-12)
  read=lambda r:r['totals']['DRAM_issued_read_atoms32B']
  diag={}
  for (cell,f),r in by.items():
   toks=dict(r['kernels'][-1]['latency_tokens_diagnostic_only']);token=toks.get('avg_mrq_latency')
   diag[cell+'_'+f]=dict(raw_printed_avg_mrq_latency=token,not_full_L2_DRAM_latency=True)
  rows.append(dict(program=program,full_input_digest=data['full_input_digest'],source_package=str(d),source_manifest_sha256=pin,source_data_sha256=sha(d/'MATCHED_FOUR_SOURCE_DATA.json'),S_CH=sc,S_DH=sd,I=interaction,R_F128=ratio,DH_cycles_above_CH_F128_percent=100*(df['cycles']/cf['cycles']-1),CH_cycle_change_percent=100*(cf['cycles']/c0['cycles']-1),DH_cycle_change_percent=100*(df['cycles']/d0['cycles']-1),DRAM_read_DH_above_CH_P0_percent=100*(read(d0)/read(c0)-1),DRAM_read_DH_above_CH_F128_percent=100*(read(df)/read(cf)-1),CH_DRAM_read_change_percent=100*(read(cf)/read(c0)-1),DH_DRAM_read_change_percent=100*(read(df)/read(d0)-1),CH_kernel_cycle_deltas=[z['cycles']-x['cycles']for x,z in zip(c0['kernels'],cf['kernels'])],DH_kernel_cycle_deltas=[z['cycles']-x['cycles']for x,z in zip(d0['kernels'],df['kernels'])],MRQ_diagnostic_prints=diag,four_identities=[{k:r[k]for k in ['cell','profile','cohort','uuid','RESULT_path','RESULT_sha256','raw_path','raw_uncompressed_sha256','cycles']}for r in data['four_closed_sources']]))
 report=dict(schema='DTC_STAGEIIA_THREE_CASE_MATCHED_F128_SYNTHESIS_V1',UTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),authority_commit='5001c3f35052f7f91f1ad41eeff83f2947a0878d',rows=rows,population_scope='Three predeclared diagnostic cases only; no first8/core32/frozen35 GM, no F128/F256 adoption.',causal_scope='Common DRAM atoms are comparable event units, but different upstream request populations; aggregate counters and MRQ means do not identify a unique critical path.',source_mapping_scope='Candidate-source formulas/dependency are not certified captured-ELF or numerical-state identities.',simulation_starts=0,new_science_grants=0,next48_released=False,goal_complete=False)
 (O/'THREE_CASE_MATCHED_DIAGNOSIS.json').write_text(json.dumps(report,indent=2)+'\n')
 lines=['# ATAX, MVT and BICG: matched F128 synthesis','','These three fixed diagnostic cases now have all four closed sources: CH-P0, CH-F128, DH-P0 and DH-F128. The data retains original-reference aliases and the new first16 identities. This is a three-case analysis, not the first8 or32/35-program population. F256 is still pending for these inputs, so this does not select a uniform F configuration.','','| Program | S_CH | S_DH | I=S_DH/S_CH | DH cycles above matched CH | CH kernel-cycle deltas | DH kernel-cycle deltas |','|---|---:|---:|---:|---:|---|---|']
 for r in rows:lines.append('| '+r['program']+' | '+format(r['S_CH'],'.6f')+' | '+format(r['S_DH'],'.6f')+' | '+format(r['I'],'.6f')+' | '+format(r['DH_cycles_above_CH_F128_percent'],'.2f')+'% | '+str(r['CH_kernel_cycle_deltas'])+' | '+str(r['DH_kernel_cycle_deltas'])+' |')
 lines+=['','A speedup above1 means fewer cycles. I above1 is a relative change and does not mean DH is faster than its own P0 or than CH. ATAX is the direct counterexample: both designs regress, CH regresses more, and DH remains slower than CH. BICG changes are exactly K2; MVT and ATAX changes are mainly K1 with small real K2 changes. No small nonzero change is relabelled exact-zero.','','## Revisiting the reported14%-32% DRAM-read gap','','| Program | DH read atoms above CH atP0 | DH read atoms above CH atF128 | CH own read change | DH own read change |','|---|---:|---:|---:|---:|']
 for r in rows:lines.append('| '+r['program']+' | '+format(r['DRAM_read_DH_above_CH_P0_percent'],'.2f')+'% | '+format(r['DRAM_read_DH_above_CH_F128_percent'],'.2f')+'% | '+format(r['CH_DRAM_read_change_percent'],'+.2f')+'% | '+format(r['DH_DRAM_read_change_percent'],'+.2f')+'% |')
 lines+=['','The original approximate14%-32% difference is reproduced in these exact P0 references. Matched F128 changes it in different directions; all three DH runs still issue more DRAM-read atoms and take more total cycles than CH. This is an observation, not proof that read volume alone caused the cycle gap. L2 input streams and filtering differ between CH and DH, so miss fractions are conditional on different request populations.','','## Why the existing means do not prove complete L2-to-DRAM latency','','| Program | CH P0 printed MRQ mean | CH F128 | DH P0 | DH F128 |','|---|---:|---:|---:|---:|']
 for r in rows:
  values=[r['MRQ_diagnostic_prints'][k]['raw_printed_avg_mrq_latency']for k in ['CH_P0','CH_F128','DH_P0','DH_F128']]
  lines.append('| '+r['program']+' | '+' | '.join(str(v)if v is not None else'MISSING'for v in values)+' |')
 lines+=['','These raw diagnostics are cumulative, request-conditioned MRQ ages from DRAM-request construction to bank assignment, not complete L2->DRAM service/return or critical-path latency. MRQ mean rises in both designs for all three inputs, even though CH gets faster in MVT and BICG. A larger scheduler window and coupled credits can change where requests wait, their age/population and ordering. The table does not quantify an end-to-end delay increase caused by the14%-32% traffic gap. Other printed means retain the established sampling/fold/tail and population limitations; they are not summed or differenced into per-kernel latency.','','## Facts, associations and remaining limits','','All three nearly remove miss-queue-full retry attempts while entry-capacity retry attempts grow. MVT CH improves despite more aggregate reservation failures and ICNT-admission blockage; ATAX CH regresses despite fewer of those events. Therefore retry totals do not monotonically explain performance and are not occupancy or critical stall cycles. Entry capacity and per-address merge limits remain distinct. No resource-expansion speedup is predicted from these counts.','','DH line-miss/tag-eviction improvements in MVT/BICG coexist with more downstream DRAM work; ATAX has more OO lower requests but slightly less DRAM work. These changes support investigating filtering/interleaving, useful concurrency, replacement and request dependencies, but do not isolate one cause. Mean PIB/service observations cannot rule out bursts, tails or local bottlenecks; unprinted counters remain missing.','','ATAX tmp dependency and MVT independent output chains are inspected candidate-source properties, with capture-ELF/numerical-state binding limits retained. Frozen trace input identity, ordered kernels, instructions and grid scope are unchanged; source inspection is not a new numerical correctness certificate.','','FR-FCFS64->128 also changes shared credits255->319. L2 capacity/MSHR/merge/missQ,850MHz DRAM and within-design L1 mechanisms stay fixed. CH PAPER_BASE commonPIB256 and DH PAPER_OO PIB128 differ; the rawDH common8 option is inactive for OO admission. Neither capacity nor physical area is matched. The old BICG f2b packet must be consumed with its frozen typed-field forward clarification4550.','','The source quartet manifests, full input digests, RESULT/raw SHA and exact per-kernel deltas are in THREE_CASE_MATCHED_DIAGNOSIS.json. Detailed source/counter/latency boundaries remain in the three B packets and independent C reviews. This synthesis starts no simulation, changes no source or runtime identity, grants no new budget and does not release48 points or edit Englishv0.23. The first16 Goal remains active until all16 terminal and final review/publication.','']
 (O/'README.md').write_text('\n'.join(lines))
 assert all(r['DH_cycles_above_CH_F128_percent']>0 for r in rows)
 assert rows[0]['I']>1 and rows[0]['S_DH']<1
 src=Path(__file__);assert src.resolve().parent==O
 files=[dict(path=p.name,sha256=sha(p),bytes=p.stat().st_size)for p in sorted(O.iterdir())if p.is_file()and p.name!='MANIFEST.json']
 (O/'MANIFEST.json').write_text(json.dumps(dict(schema='DTC_STAGEIIA_THREE_CASE_SYNTHESIS_MANIFEST_V1',files=files),indent=2)+'\n')
 print(json.dumps(dict(path=str(O),manifest_sha256=sha(O/'MANIFEST.json'),rows=[{k:r[k]for k in ['program','I','DH_cycles_above_CH_F128_percent','DRAM_read_DH_above_CH_P0_percent','DRAM_read_DH_above_CH_F128_percent']}for r in rows],new_simulations=0)))

if __name__=='__main__':main()
